import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

square_matrix_multiplication_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

// Tile size for shared memory
#define TILE_SIZE 32

__global__ void matmul_kernel_shared_memory_unrolled(const float* A, const float* B, float* C, int N) {
    // Block-wide shared memory for tiles of A and B
    __shared__ float sA[TILE_SIZE][TILE_SIZE];
    __shared__ float sB[TILE_SIZE][TILE_SIZE];

    // Thread indices within the block
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Global row and column for the current thread
    int row = blockIdx.y * TILE_SIZE + ty;
    int col = blockIdx.x * TILE_SIZE + tx;

    float sum = 0.0f;

    // Iterate over tiles
    int numTiles = (N + TILE_SIZE - 1) / TILE_SIZE;
    for (int t = 0; t < numTiles; ++t) {
        // Load tiles from global memory to shared memory
        int aRow = blockIdx.y * TILE_SIZE + ty;
        int aCol = t * TILE_SIZE + tx;
        if (aRow < N && aCol < N) {
            sA[ty][tx] = A[aRow * N + aCol];
        } else {
            sA[ty][tx] = 0.0f; // Pad with zeros if out of bounds
        }

        int bRow = t * TILE_SIZE + ty;
        int bCol = blockIdx.x * TILE_SIZE + tx;
        if (bRow < N && bCol < N) {
            sB[ty][tx] = B[bRow * N + bCol];
        } else {
            sB[ty][tx] = 0.0f; // Pad with zeros if out of bounds
        }

        __syncthreads(); // Wait for all threads to load their data

        // Perform dot product on shared memory tiles with unrolling
        if (row < N && col < N) {
            #pragma unroll
            for (int k = 0; k < TILE_SIZE; ++k) {
                sum += sA[ty][k] * sB[k][tx];
            }
        }

        __syncthreads(); // Wait for all threads to finish using shared memory
    }

    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor square_matrix_multiplication_cuda(torch::Tensor A, torch::Tensor B) {
    // Ensure inputs are contiguous
    A = A.contiguous();
    B = B.contiguous();

    int N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 block_size(TILE_SIZE, TILE_SIZE);
    dim3 grid_size((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel_shared_memory_unrolled<<<grid_size, block_size>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

square_matrix_multiplication_cpp_source = (
    "torch::Tensor square_matrix_multiplication_cuda(torch::Tensor A, torch::Tensor B);"
)

square_matrix_multiplication_module = load_inline(
    name="square_matrix_multiplication",
    cpp_sources=square_matrix_multiplication_cpp_source,
    cuda_sources=square_matrix_multiplication_source,
    functions=["square_matrix_multiplication_cuda"],
    verbose=True,
    extra_cflags=["-O3"],
    extra_ldflags=[""],
)

